import React, { useEffect, useRef, useState } from 'react';

/**
 * Hands-free voice intake banner. Where the browser supports the Web Speech
 * API it does real speech recognition and echoes back what it heard; where
 * it doesn't (or permission is denied) it falls back to a simulated
 * "listening" pulse so the trauma-informed hands-free flow can still be
 * demonstrated end to end.
 */
export default function VoiceGuideBanner({ onDismiss, onTranscript }) {
  const [listening, setListening] = useState(false);
  const [heard, setHeard] = useState('');
  const [supported, setSupported] = useState(true);
  const recognitionRef = useRef(null);

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setSupported(false);
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onresult = (event) => {
      const transcript = Array.from(event.results)
        .map((r) => r[0].transcript)
        .join(' ');
      setHeard(transcript);
      onTranscript?.(transcript);
    };
    recognition.onerror = () => setListening(false);
    recognition.onend = () => setListening(false);

    recognitionRef.current = recognition;
    return () => recognition.stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleListening = () => {
    if (!supported) {
      setListening((l) => !l); // simulated pulse only
      return;
    }
    if (listening) {
      recognitionRef.current?.stop();
      setListening(false);
    } else {
      try {
        recognitionRef.current?.start();
        setListening(true);
      } catch {
        setListening(false);
      }
    }
  };

  return (
    <div className="voice-banner">
      <div className="voice-banner-left">
        <span className={`voice-pulse ${listening ? 'on' : ''}`} aria-hidden="true" />
        <div>
          <strong>{listening ? 'Listening for navigation & reporting commands…' : 'Voice Guide ready'}</strong>
          <p>
            {supported
              ? 'Speak naturally to narrate what happened — SafeTrace will transcribe it into your report.'
              : 'Hands-free speech intake simulated in this browser.'}
            {heard && <span className="voice-heard"> "{heard}"</span>}
          </p>
        </div>
      </div>
      <div className="voice-banner-actions">
        <button className="btn btn-ghost btn-sm" onClick={toggleListening}>
          {listening ? '⏸ Pause' : '🎙️ Start Listening'}
        </button>
        <button className="voice-banner-dismiss" onClick={onDismiss} aria-label="Dismiss voice guide banner">
          ✕
        </button>
      </div>
    </div>
  );
}
